var PHOTO_BYTES = 122967339;
var ROOT = new URL('./', self.location.href).href;
var PAGE_WAIT = 3500;
var FAIL_LIMIT = 8;                    // more failures than this and the install is abandoned and tried again next visit

function abs(u) { return new URL(u, ROOT).href; }

function say(msg) {
  return self.clients.matchAll({ includeUncontrolled: true }).then(function (all) {
    all.forEach(function (c) { c.postMessage(msg); });
  });
}

/* Run `jobs` (functions returning promises) at most n at a time. */
function pool(jobs, n) {
  var i = 0;
  function next() {
    if (i >= jobs.length) { return Promise.resolve(); }
    return jobs[i++]().then(next);
  }
  var runners = [];
  for (var k = 0; k < n; k++) { runners.push(next()); }
  return Promise.all(runners);
}

self.addEventListener('install', function (event) {
  event.waitUntil(caches.open(CORE).then(function (cache) {
    var failed = 0;
    var jobs = PRECACHE.map(function (u) {
      return function () {
        return fetch(new Request(abs(u), { cache: 'reload' })).then(function (res) {
          if (res.ok) { return cache.put(abs(u), res); }
          failed++;
        }).catch(function () { failed++; });
      };
    });
    return pool(jobs, 6).then(function () {
      if (failed > FAIL_LIMIT) {
        return caches.delete(CORE).then(function () { throw new Error('offline copy incomplete'); });
      }
      return self.skipWaiting();
    });
  }));
});

/* Photographs saved by an older version: drop any whose address is no longer listed, or whose size differs from the list (the
   photograph was replaced at the same address), so a replaced or withdrawn photograph never outlives the version that lists it. */
function prunePhotos() {
  var want = {};
  PHOTO_LIST.forEach(function (item) { want[abs(item[0])] = item[1]; });
  return caches.open(PHOTOS).then(function (cache) {
    return cache.keys().then(function (reqs) {
      return Promise.all(reqs.map(function (req) {
        var bytes = want[req.url];
        if (bytes === undefined) { return cache.delete(req); }
        return cache.match(req).then(function (res) {
          var len = res ? Number(res.headers.get('content-length')) : 0;
          if (len && len !== bytes) { return cache.delete(req); }
        });
      }));
    });
  });
}

self.addEventListener('activate', function (event) {
  event.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.filter(function (k) { return k.indexOf('sc-core-') === 0 && k !== CORE; })
      .map(function (k) { return caches.delete(k); }));
  }).then(prunePhotos).then(function () { return self.clients.claim(); }));
});

/* A saved copy of a page: the exact address, then without the query, then the folder form of the address. */
function saved(cache, req, url) {
  return cache.match(req).then(function (hit) {
    if (hit) { return hit; }
    return cache.match(req, { ignoreSearch: true });
  }).then(function (hit) {
    if (hit) { return hit; }
    if (url.pathname.slice(-1) !== '/' && url.pathname.split('/').pop().indexOf('.') === -1) {
      return cache.match(url.origin + url.pathname + '/');
    }
    return null;
  });
}

function keep(cache, req, res) {
  if (res && res.ok && !res.redirected && res.type === 'basic') {
    var copy = res.clone();
    cache.put(req, copy);
  }
}

/* Offline, on an address that was never saved. It is not the not-found page: the page may well exist. */
function offlineNotice() {
  var link = function (path, label) { return '<li><a href="' + abs(path) + '">' + label + '</a></li>'; };
  var html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
    '<meta name="robots" content="noindex, nofollow"><title>Offline · Boys on Tour</title>' +
    '<style>body{font:18px/1.5 system-ui,-apple-system,sans-serif;margin:0;padding:24px;max-width:36rem;color:#F2F3F4;background:#111214;color-scheme:dark}' +
    'h1{font:700 32px/1.1 "DIN Condensed","Avenir Next Condensed",Bahnschrift,"Roboto Condensed","Arial Narrow",sans-serif-condensed,"Helvetica Neue",Arial,sans-serif;text-transform:uppercase}a{color:#8DBBFF;display:inline-block;padding:8px 0}' +
    '</style></head><body>' +
    '<h1>You are offline</h1><p>This page was not saved on this device, and the connection is not answering. The pages that were saved:</p><ul>' +
    link('', 'Home') + link('eat/', 'Eat and drink') + link('see/', 'See') + link('errands/', 'Errands') + link('map/', 'Map list') +
    link('about/', 'About') + '</ul></body></html>';
  return new Response(html, { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
}

function page(req, url) {
  return caches.open(CORE).then(function (cache) {
    var net = fetch(req);
    var timer;
    var slow = new Promise(function (resolve) { timer = setTimeout(function () { resolve(null); }, PAGE_WAIT); });
    return Promise.race([net, slow]).then(function (res) {
      clearTimeout(timer);
      if (res && res.status >= 500) {                          // the server is failing: a saved copy beats an error page
        return saved(cache, req, url).then(function (hit) { return hit || res; });
      }
      if (res) { keep(cache, req, res); return res; }
      // the network is slow: show the saved copy if there is one, and refresh it in the background
      return saved(cache, req, url).then(function (hit) {
        if (!hit) { return net; }
        net.then(function (r) { keep(cache, req, r); }).catch(function () {});
        return hit;
      });
    }).catch(function () {
      clearTimeout(timer);
      return saved(cache, req, url).then(function (hit) { return hit || offlineNotice(); });
    });
  });
}

function photo(req) {
  return caches.match(req).then(function (hit) {          // saved earlier (the hero is saved with the pages, the rest as viewed)
    if (hit) { return hit; }
    return fetch(req).then(function (res) {
      if (res.ok && res.type === 'basic') {
        var copy = res.clone();
        caches.open(PHOTOS).then(function (cache) { return cache.put(req, copy); });
      }
      return res;
    }).catch(function () { return Response.error(); });      // offline and not saved: the image simply does not load
  });
}

function asset(req) {
  return caches.match(req).then(function (hit) {
    if (hit) { return hit; }
    return fetch(req).then(function (res) {
      if (res.ok && res.type === 'basic') {
        var copy = res.clone();
        caches.open(CORE).then(function (cache) { return cache.put(req, copy); });
      }
      return res;
    }).catch(function () { return Response.error(); });
  });
}

self.addEventListener('fetch', function (event) {
  var req = event.request;
  if (req.method !== 'GET') { return; }
  var url = new URL(req.url);
  if (url.href.indexOf(ROOT) !== 0) { return; }              // another host, or outside this site: not ours
  var rel = url.href.slice(ROOT.length);
  if (rel === 'sw.js') { return; }
  if (req.mode === 'navigate' || rel.indexOf('assets/data/') === 0) {
    event.respondWith(page(req, url));
  } else if (rel.indexOf('img/') === 0) {
    event.respondWith(photo(req));
  } else {
    event.respondWith(asset(req));
  }
});

/* Messages from the "Use it offline" page. */
function heal(list) {                                  // fetch again the pages a bad connection left out of the install
  return caches.open(CORE).then(function (cache) {
    var jobs = list.map(function (u) {
      return function () {
        return fetch(new Request(abs(u), { cache: 'reload' })).then(function (res) {
          if (res.ok) { return cache.put(abs(u), res); }
        }).catch(function () {});
      };
    });
    return pool(jobs, 4);
  });
}

function status() {
  return caches.keys().then(function (keys) {
    var hasCore = keys.indexOf(CORE) !== -1;
    var coreKeys = hasCore ? caches.open(CORE).then(function (c) { return c.keys(); }) : Promise.resolve([]);
    var photoKeys = keys.indexOf(PHOTOS) !== -1 ? caches.open(PHOTOS).then(function (c) { return c.keys(); }) : Promise.resolve([]);
    return Promise.all([coreKeys, photoKeys]).then(function (r) {
      var have = {};
      r[0].forEach(function (q) { have[q.url] = true; });
      var missing = hasCore ? PRECACHE.filter(function (u) { return !have[abs(u)]; }) : [];
      var savedPhotos = {};
      r[1].forEach(function (q) { savedPhotos[q.url] = true; });
      var n = 0;
      var left = 0;
      PHOTO_LIST.forEach(function (item) { if (savedPhotos[abs(item[0])]) { n++; } else { left += item[1]; } });
      return say({ type: 'status', version: VERSION, core: hasCore, missing: missing.length, photos: n, photosTotal: PHOTO_LIST.length,
                   photoBytes: PHOTO_BYTES, photoBytesLeft: left }).then(function () {
        if (missing.length) { return heal(missing); }
      });
    });
  });
}

function savePhotos() {
  return caches.open(PHOTOS).then(function (cache) {
    var done = 0;
    var failed = 0;
    var total = PHOTO_LIST.length;
    var jobs = PHOTO_LIST.map(function (item) {
      return function () {
        var u = abs(item[0]);
        return cache.match(u).then(function (hit) {
          if (hit) { return null; }
          return fetch(u).then(function (res) {
            if (res.ok) { return cache.put(u, res); }
            failed++;
          });
        }).catch(function () { failed++; }).then(function () {
          done++;
          if (done % 10 === 0 || done === total) { return say({ type: 'photos-progress', done: done, total: total, failed: failed }); }
        });
      };
    });
    return pool(jobs, 4).then(function () { return say({ type: 'photos-done', done: done, total: total, failed: failed }); });
  });
}

self.addEventListener('message', function (event) {
  var d = event.data || {};
  if (d.type === 'status') {
    event.waitUntil(status());
  } else if (d.type === 'save-photos') {
    event.waitUntil(savePhotos());
  } else if (d.type === 'remove-all') {
    event.waitUntil(caches.keys().then(function (keys) {
      return Promise.all(keys.filter(function (k) { return k.indexOf('sc-core-') === 0 || k === PHOTOS; }).map(function (k) { return caches.delete(k); }));
    }).then(function () { return say({ type: 'removed' }); }));
  }
});
